it('manages tool registration and retrieval (specs/hal-engine-tool-input-validation/spec.md#L8)', () => {
  const registry = new ToolRegistry();
  const def = {name: 't', description: 'd', inputSchema: {}, promptInstructions: 'pi', examplePrompts: ['ep']};
  registry.register(def, async () => 'ok');

  const tool = registry.get('t');
  expect({
    hasT: registry.has('t'),
    hasMissing: registry.has('missing'),
    tName: tool?.definition.name,
    missing: registry.get('missing'),
    defs: registry.getDefinitions().length,
    instructions: registry.getPromptInstructions(),
    examples: registry.getExamplePrompts(),
  }).toEqual({
    hasT: true,
    hasMissing: false,
    tName: 't',
    missing: undefined,
    defs: 1,
    instructions: ['t: pi'],
    examples: ['ep'],
  });
});

